<script lang="ts">
 import {catalogApi} from '$lib/api/catalog';import type {LibraryKind} from '$lib/rules/library';import MonsterSheet from './MonsterSheet.svelte';import OptionReference from './OptionReference.svelte';
 export let kind:LibraryKind;export let entryKey:string;let record:any=null;let error='';let current='';let level=1;
 $: if(`${kind}:${entryKey}`!==current){current=`${kind}:${entryKey}`;load(kind,entryKey,current);}
 async function load(k:LibraryKind,key:string,id:string){record=null;error='';try{const data=k==='monsters'?await catalogApi.getMonster(key):k==='items'?await catalogApi.getItem(key):k==='spells'?await catalogApi.getSpell(key):await catalogApi.getOption(key);if(id===current)record=data;}catch(cause){if(id===current)error=cause instanceof Error?cause.message:'No se pudo cargar.';}}
</script>
<section class="text-neutral space-y-2">{#if error}<p role="alert" class="text-error text-sm">{error}</p><button class="btn btn-sm" on:click={()=>load(kind,entryKey,current)}>Reintentar</button>{:else if !record}<p role="status">Cargando ficha…</p>{:else if kind==='monsters'}<MonsterSheet monster={record}/>{:else if kind==='options'}{#if ['class','subclass'].includes(record.type)}<label class="block text-sm">Nivel de consulta<select class="select select-bordered select-sm w-full text-neutral" bind:value={level}>{#each Array.from({length:20},(_,i)=>i+1) as n}<option value={n}>Nivel {n}</option>{/each}</select></label>{/if}<OptionReference optionKey={entryKey} {level}/>{:else}<h3 class="font-medieval text-xl font-bold">{record.name}</h3><a class="link text-xs" href={`/sources#${record.catalogSource.key}`} target="_blank" rel="noreferrer">{record.catalogSource.name} · {record.catalogSource.edition}</a>{#if kind==='spells'}<p class="text-sm">{record.level===0?'Truco':`Nivel ${record.level}`} · {record.school} · {record.castingTime}<br/>{record.range} · {record.duration} · {record.components}{record.concentration?' · Concentración':''}{record.ritual?' · Ritual':''}</p>{:else}<p class="text-sm">{record.rarity} · {record.cost??0} GP{record.weight?` · ${record.weight} ${record.weight_unit||''}`:''}</p>{#if record.catalogData?.weaponData}<p class="text-sm">Daño: {record.catalogData.weaponData.damageDice}{record.catalogData.weaponData.properties.versatile?`/${record.catalogData.weaponData.properties.versatile}`:''} · {record.catalogData.weaponData.damageType}</p>{/if}{/if}{#if record.contentMode}<p class="text-xs">Datos mecánicos; consultá las reglas completas en la publicación.</p>{/if}<p class="whitespace-pre-wrap break-words text-sm">{record.desc}</p>{#if record.higherLevel}<p class="whitespace-pre-wrap text-sm">{record.higherLevel}</p>{/if}{#each record.references||[] as ref}<a class="link text-xs block" href={ref.url} target="_blank" rel="noreferrer">Consultar {ref.provider}</a>{/each}{/if}</section>
